const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || source.text || source.fileName || source.targetName || args.fileName || args.targetName || message.text || payload.text || '').trim();
const fileId = source.fileId || source.targetId || args.fileId || args.targetId || payload.fileId || payload.targetId || '';
let fileName = String(source.fileName || source.targetName || args.fileName || args.targetName || payload.fileName || payload.targetName || '').trim();
let newName = String(source.newName || args.newName || payload.newName || '').trim();
const targetFolderId = source.targetFolderId || source.folderId || source.parentId || args.targetFolderId || args.folderId || args.parentId || payload.targetFolderId || payload.folderId || '';
const targetFolderName = String(source.targetFolderName || source.folderName || args.targetFolderName || args.folderName || payload.targetFolderName || payload.folderName || '').trim();
const cleaned = raw.replace(/^(copy file|nhan ban file|tao ban sao file|duplicate file|copy template)\s*/i, '').trim();
if (!fileName) { const m = cleaned.match(/^(.*?)\s+(?:thanh|to)\s+(.*)$/i); if (m) { fileName = m[1].trim(); if (!newName) newName = m[2].trim(); } else { fileName = cleaned; } }


// Stage 11 exact-id safety guard
const __stage11Pick = (...values) => {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value;
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
    if (typeof value === 'boolean') return value;
  }
  return '';
};
const __stage11Source = source || {};
const __stage11Args = args || __stage11Source.args || __stage11Source.payload?.args || {};
const __stage11Payload = typeof payload !== 'undefined' ? payload : (__stage11Source.payload || {});
const __stage11IdFields = ["fileId", "targetId"];
const __stage11AlsoFields = [];
const __stage11HasId = Boolean(__stage11Pick(...__stage11IdFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11HasAlso = __stage11AlsoFields.length === 0 || Boolean(__stage11Pick(...__stage11AlsoFields.map((field) =>
  __stage11Source[field] || __stage11Args[field] || __stage11Payload[field]
)));
const __stage11Allowed = __stage11HasId && __stage11HasAlso;
const __stage11Response = __stage11Allowed ? '' : "Mia chưa copy file vì hành động này cần fileId cụ thể. Bạn hãy tìm file trước, chọn đúng file, rồi gửi lại kèm fileId và tên bản sao nếu cần.";

return [{ json: { ...source, payload, message, chatId, raw, fileId, targetId: fileId, fileName, targetName: fileName, newName, targetFolderId, targetFolderName, hasTarget: Boolean(__stage11Allowed && (fileId || fileName)), response: __stage11Response ? __stage11Response : (fileId || fileName) ? '' : '📄 <b>Copy file</b>\n\nVi du: copy file mau hop dong thanh hop dong khach A' } }];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');
const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};
const formatDate = (value) => {
  if (!value) return '';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? '' : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

const source = $('Prepare Action').item.json;
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) return [{ json: { ...source, found: false, response: 'Khong tim thay file phu hop.' } }];
const file = rows[0];
return [{ json: { ...source, found: true, fileId: file.id, targetId: file.id || source.targetId || source.fileId || '', fileName: file.name || source.fileName || source.targetName || '', targetName: file.name || source.targetName || source.fileName || '', targetFolderName: source.targetFolderName || source.folderName || '', webViewLink: file.webViewLink || '', mimeType: file.mimeType || '', modifiedTime: file.modifiedTime || '' } }];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const source = $('Prepare Action').item.json || {};
const item = $input.item.json || {};

const fileName =
  item.name ||
  source.newName ||
  source.fileName ||
  source.targetName ||
  'Không rõ tên';

const fileId =
  item.id ||
  item.fileId ||
  source.newFileId ||
  source.fileId ||
  source.targetId ||
  '';

const link =
  item.webViewLink ||
  item.webContentLink ||
  (fileId ? `https://drive.google.com/file/d/${fileId}/view` : '');

const mimeType =
  item.mimeType ||
  source.mimeType ||
  '';

let text = '✅ <b>Đã copy file</b>\n\n';

text += `📄 <b>${escapeHtml(fileName)}</b>\n`;

if (mimeType) {
  text += `Loại: <code>${escapeHtml(mimeType)}</code>\n`;
}

if (fileId) {
  text += `ID: <code>${escapeHtml(fileId)}</code>\n`;
}

if (link) {
  text += `🔗 <a href="${escapeHtml(link)}">Mở file</a>\n`;
}

return [{
  json: {
    chatId: source.chatId || item.chatId,
    text: text.trim(),
  },
}];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
